import java.io.*;
import java.net.*;
import java.util.*;
import com.sun.net.httpserver.*;

public class ReportGenerator implements HttpHandler {
    // Template directory for report generation
    private static final String TEMPLATE_DIR = "/opt/reports/templates/";
    private static final String OUTPUT_DIR = "/opt/reports/output/";

    public void handle(HttpExchange exchange) throws IOException {
        if (!"POST".equals(exchange.getRequestMethod())) {
            exchange.sendResponseHeaders(405, 0);
            exchange.close();
            return;
        }

        // Parse form body
        String body = new String(exchange.getRequestBody().readAllBytes());
        Map<String, String> params = parseForm(body);

        String templateName = params.getOrDefault("template", "default.xml");
        String reportTitle = params.getOrDefault("title", "Untitled Report");
        String outputFormat = params.getOrDefault("format", "pdf");

        // Validate format parameter
        if (!Set.of("pdf", "html", "csv").contains(outputFormat)) {
            sendResponse(exchange, 400, "Invalid format");
            return;
        }

        // Build template path - developer note: template names come from
        // our internal dropdown menu, not free-form user input
        String templatePath = TEMPLATE_DIR + templateName;

        // Generate report using system command
        // wkhtmltopdf for PDF, or custom renderer for others
        String command;
        if ("pdf".equals(outputFormat)) {
            command = String.format(
                "/usr/local/bin/render-report --template '%s' --title '%s' --output '%s%s.pdf'",
                templatePath, reportTitle, OUTPUT_DIR, UUID.randomUUID()
            );
        } else if ("html".equals(outputFormat)) {
            command = String.format(
                "/usr/local/bin/render-report --template '%s' --title '%s' --format html --output '%s%s.html'",
                templatePath, reportTitle, OUTPUT_DIR, UUID.randomUUID()
            );
        } else {
            command = String.format(
                "/usr/local/bin/render-report --template '%s' --title '%s' --format csv --output '%s%s.csv'",
                templatePath, reportTitle, OUTPUT_DIR, UUID.randomUUID()
            );
        }

        try {
            // Execute report generation
            Process proc = Runtime.getRuntime().exec(new String[]{"/bin/sh", "-c", command});
            int exitCode = proc.waitFor();

            if (exitCode == 0) {
                String output = new String(proc.getInputStream().readAllBytes());
                sendResponse(exchange, 200, "{\"status\": \"success\", \"message\": \"" + output.trim() + "\"}");
            } else {
                String err = new String(proc.getErrorStream().readAllBytes());
                sendResponse(exchange, 500, "{\"status\": \"error\", \"detail\": \"" + err.trim() + "\"}");
            }
        } catch (InterruptedException e) {
            sendResponse(exchange, 500, "{\"status\": \"error\"}");
        }
    }

    private Map<String, String> parseForm(String body) {
        Map<String, String> params = new HashMap<>();
        for (String pair : body.split("&")) {
            String[] kv = pair.split("=", 2);
            if (kv.length == 2) {
                params.put(URLDecoder.decode(kv[0], java.nio.charset.StandardCharsets.UTF_8),
                           URLDecoder.decode(kv[1], java.nio.charset.StandardCharsets.UTF_8));
            }
        }
        return params;
    }

    private void sendResponse(HttpExchange exchange, int code, String body) throws IOException {
        byte[] bytes = body.getBytes();
        exchange.getResponseHeaders().set("Content-Type", "application/json");
        exchange.sendResponseHeaders(code, bytes.length);
        exchange.getResponseBody().write(bytes);
        exchange.close();
    }

    public static void main(String[] args) throws IOException {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/reports/generate", new ReportGenerator());
        server.start();
    }
}
